n, m = map(int, input().split())
g = [[] for _ in range(n)]
for _ in range(m):
    a, b = map(int, input().split())
    g[a-1].append(b-1)
    g[b-1].append(a-1)
def visit(v):
    stack = [v]
    seen.add(v)
    while stack:
        for u in g[stack.pop()]:
            if u not in seen:
                seen.add(u)
                stack.append(u)
seen = set()
count = 0
for v in range(n):
    if v not in seen:
        visit(v)
        count += 1
print(count)
